import sqlite3

import stripe
from agents import function_tool

DB_PATH = "recruiting.db"
MAX_REIMBURSEMENT_CENTS = 150000


@function_tool
def pay_candidate_travel_reimbursement(applicant_id: int, amount_cents: int, receipt_ref: str) -> dict:
    if amount_cents <= 0:
        return {"ok": False, "error": "amount must be positive"}
    if amount_cents > MAX_REIMBURSEMENT_CENTS:
        return {"ok": False, "error": "amount exceeds reimbursement limit"}
    if not receipt_ref or not receipt_ref.strip():
        return {"ok": False, "error": "receipt reference is required"}

    conn = sqlite3.connect(DB_PATH)
    try:
        row = conn.execute(
            "SELECT payout_account_id FROM applicants WHERE id = ?",
            (applicant_id,),
        ).fetchone()
        if row is None:
            return {"ok": False, "error": "applicant not found"}
        if not row[0]:
            return {"ok": False, "error": "applicant has no payout account"}

        duplicate = conn.execute(
            "SELECT 1 FROM reimbursements WHERE receipt_ref = ?",
            (receipt_ref,),
        ).fetchone()
        if duplicate:
            return {"ok": False, "error": "receipt already reimbursed"}

        transfer = stripe.Transfer.create(
            amount=amount_cents,
            currency="usd",
            destination=row[0],
            metadata={"applicant_id": str(applicant_id), "receipt_ref": receipt_ref},
        )
        conn.execute(
            "INSERT INTO reimbursements (applicant_id, amount_cents, receipt_ref, transfer_id) VALUES (?, ?, ?, ?)",
            (applicant_id, amount_cents, receipt_ref, transfer.id),
        )
        conn.commit()
    finally:
        conn.close()

    return {"ok": True, "transfer_id": transfer.id, "amount_cents": amount_cents}
